export class Game {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private playerX: number;
  private playerY: number;
  private playerAngle: number;
  private bullets: { x: number, y: number, angle: number }[];
  private enemies: { x: number, y: number }[];
  private score: number;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d')!;
    this.playerX = canvas.width / 2;
    this.playerY = canvas.height / 2;
    this.playerAngle = 0;
    this.bullets = [];
    this.enemies = [{ x: 100, y: 100 }, { x: 300, y: 200 }];
    this.score = 0;
  }

  update(dt: number): void {
    // Update player position and angle
    this.playerX += Math.cos(this.playerAngle) * 100 * dt;
    this.playerY += Math.sin(this.playerAngle) * 100 * dt;

    // Update bullets
    for (const bullet of this.bullets) {
      bullet.x += Math.cos(bullet.angle) * 500 * dt;
      bullet.y += Math.sin(bullet.angle) * 500 * dt;
    }

    // Check for collisions with enemies
    for (const bullet of this.bullets) {
      for (const enemy of this.enemies) {
        if (Math.hypot(bullet.x - enemy.x, bullet.y - enemy.y) < 20) {
          this.score += 1;
          this.enemies = this.enemies.filter(e => e !== enemy);
          break;
        }
      }
    }
  }

  draw(): void {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

    // Draw player
    this.ctx.save();
    this.ctx.translate(this.playerX, this.playerY);
    this.ctx.rotate(this.playerAngle);
    this.ctx.fillStyle = 'blue';
    this.ctx.fillRect(-10, -10, 20, 20);
    this.ctx.restore();

    // Draw bullets
    for (const bullet of this.bullets) {
      this.ctx.fillStyle = 'yellow';
      this.ctx.beginPath();
      this.ctx.arc(bullet.x, bullet.y, 5, 0, Math.PI * 2);
      this.ctx.fill();
    }

    // Draw enemies
    for (const enemy of this.enemies) {
      this.ctx.fillStyle = 'red';
      this.ctx.beginPath();
      this.ctx.arc(enemy.x, enemy.y, 15, 0, Math.PI * 2);
      this.ctx.fill();
    }

    // Draw score
    this.ctx.fillStyle = 'white';
    this.ctx.font = '20px Arial';
    this.ctx.fillText(`Score: ${this.score}`, 10, 20);
  }
}

export class GameLoop {
  private game: Game;
  private lastTime: number;

  constructor(game: Game) {
    this.game = game;
    this.lastTime = performance.now();
  }

  start(): void {
    this.step();
  }

  private step(): void {
    const now = performance.now();
    const dt = (now - this.lastTime) / 1000;
    this.game.update(dt);
    this.game.draw();
    this.lastTime = now;
    requestAnimationFrame(() => this.step());
  }
}

export class InputHandler {
  private keys: { [key: string]: boolean } = {};

  constructor() {
    window.addEventListener('keydown', (e) => this.onKeyDown(e));
    window.addEventListener('keyup', (e) => this.onKeyUp(e));
  }

  private onKeyDown(e: KeyboardEvent): void {
    this.keys[e.key] = true;
  }

  private onKeyUp(e: KeyboardEvent): void {
    this.keys[e.key] = false;
  }

  public isKeyDown(key: string): boolean {
    return this.keys[key] || false;
  }
}

export function createCanvas(width: number, height: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

export function render(ctx: CanvasRenderingContext2D, frame: number): void {
  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  ctx.fillStyle = 'rgb(255, 255, 255)';
  ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  ctx.fillStyle = 'rgb(0, 0, 0)';
  ctx.fillText(`Frame ${frame}`, 10, 20);
}

export class Cheese {
  x: number;
  y: number;
  z: number;
  speed: number;

  constructor(x: number, y: number, z: number, speed: number) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.speed = speed;
  }

  move(dx: number, dy: number, dz: number): void {
    this.x += dx * this.speed;
    this.y += dy * this.speed;
    this.z += dz * this.speed;
  }
}

export class Enemy {
  x: number;
  y: number;
  z: number;
  speed: number;

  constructor(x: number, y: number, z: number, speed: number) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.speed = speed;
  }

  update(playerX: number, playerY: number, playerZ: number, dt: number) {
    const dx = playerX - this.x;
    const dy = playerY - this.y;
    const dz = playerZ - this.z;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
    if (dist > 0) {
      this.x += dx / dist * this.speed * dt;
      this.y += dy / dist * this.speed * dt;
      this.z += dz / dist * this.speed * dt;
    }
  }
}

