const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const board = new THREE.Object3D();
const pieces = [];

function createBoard() {
  for (let i = 0; i < 8; i++) {
    for (let j = 0; j < 8; j++) {
      const color = (i + j) % 2 === 0 ? 0x444444 : 0x888888;
      const geometry = new THREE.BoxGeometry(1, 0.1, 1);
      const material = new THREE.MeshBasicMaterial({ color });
      const cube = new THREE.Mesh(geometry, material);
      cube.position.set(i - 3.5, 0, j - 3.5);
      board.add(cube);
    }
  }
}

function createPieces() {
  const pieceTypes = ['R', 'N', 'B', 'Q', 'K', 'P'];
  for (let i = 0; i < 8; i++) {
    for (let j = 0; j < 8; j++) {
      const type = pieceTypes[Math.floor(Math.random() * pieceTypes.length)];
      const color = Math.random() > 0.5 ? 0xffffff : 0x000000;
      const geometry = new THREE.BoxGeometry(0.8, 0.8, 0.8);
      const material = new THREE.MeshBasicMaterial({ color });
      const piece = new THREE.Mesh(geometry, material);
      piece.position.set(i - 3.5, 0.4, j - 3.5);
      pieces.push({ piece, type, color });
      board.add(piece);
    }
  }
}

function animate() {
  requestAnimationFrame(animate);
  renderer.render(scene, camera);
}

camera.position.z = 10;
createBoard();
createPieces();
scene.add(board);
animate();

export function AI(board) {
  // Simple AI logic: move the first piece it finds that can move
  for (let i = 0; i < board.length; i++) {
    for (let j = 0; j < board[i].length; j++) {
      if (board[i][j] && canMove(board, i, j)) {
        return { from: { x: i, y: j }, to: findMove(board, i, j) };
      }
    }
  }
  return null;
}

function canMove(board, x, y) {
  // Check if the piece at (x, y) can move to any adjacent square
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  for (const [dx, dy] of directions) {
    const nx = x + dx;
    const ny = y + dy;
    if (nx >= 0 && nx < board.length && ny >= 0 && ny < board[0].length && !board[nx][ny]) {
      return true;
    }
  }
  return false;
}

function findMove(board, x, y) {
  // Find the first adjacent square that the piece can move to
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  for (const [dx, dy] of directions) {
    const nx = x + dx;
    const ny = y + dy;
    if (nx >= 0 && nx < board.length && ny >= 0 && ny < board[0].length && !board[nx][ny]) {
      return { x: nx, y: ny };
    }
  }
  return { x, y };
}

