import { LedgerState } from './ledger';

export function revertToState(ledger: LedgerState, targetIndex: number): LedgerState {
  if (targetIndex < 0 || targetIndex >= ledger.history.length) {
    throw new Error('Invalid target index');
  }
  ledger.balance = ledger.history[targetIndex].balance;
  ledger.transactions = ledger.history[targetIndex].transactions.slice();
  ledger.history = ledger.history.slice(0, targetIndex + 1);
  return ledger;
}

export interface Account {
  id: number;
  balance: number;
}

export interface Transaction {
  id: number;
  type: 'deposit' | 'withdrawal';
  amount: number;
}

export class Ledger {
  private accounts: Account[] = [];
  private transactions: Transaction[] = [];

  constructor() {}

  public deposit(accountId: number, amount: number): void {
    const account = this.accounts.find(a => a.id === accountId);
    if (!account) {
      throw new Error(`Account ${accountId} not found`);
    }
    account.balance += amount;
    this.transactions.push({ id: this.transactions.length + 1, type: 'deposit', amount });
  }

  public withdraw(accountId: number, amount: number): void {
    const account = this.accounts.find(a => a.id === accountId);
    if (!account) {
      throw new Error(`Account ${accountId} not found`);
    }
    if (account.balance < amount) {
      throw new Error(`Insufficient balance in account ${accountId}`);
    }
    account.balance -= amount;
    this.transactions.push({ id: this.transactions.length + 1, type: 'withdrawal', amount });
  }

  public showBalance(accountId: number): number {
    const account = this.accounts.find(a => a.id === accountId);
    if (!account) {
      throw new Error(`Account ${accountId} not found`);
    }
    return account.balance;
  }

  public getHistory(): Transaction[] {
    return this.transactions;
  }
}

export interface BudgetItem {
  id: number;
  description: string;
