export function splitExpense(description: string, amount: number, paidBy: string, forWhom: string[]): BudgetItem {
  return { id: Date.now(), description, amount, paidBy, forWhom };
}

export function calculateOwes(items: BudgetItem[]): { [key: string]: number } {
  const owes: { [key: string]: number } = {};
  for (const item of items) {
    const perPerson = item.amount / item.forWhom.length;
    for (const whom of item.forWhom) {
      owes[whom] = (owes[whom] || 0) + perPerson;
    }
  }
  return owes;
}

