import { Expense, Balance } from './types';

export function splitExpense(expense: Expense): Balance[] {
  const total = expense.amount;
  const numFriends = expense.friends.length;
  const eachPays = total / numFriends;

  return expense.friends.map(friend => ({
    friend,
    amount: eachPays
  }));
}

export function calculateBalances(expenses: Expense[]): Balance[] {
  const balances: { [key: string]: number } = {};

  expenses.forEach(expense => {
    const total = expense.amount;
    const numFriends = expense.friends.length;
    const eachPays = total / numFriends;

    expense.friends.forEach(friend => {
      balances[friend] = (balances[friend] || 0) + eachPays;
    });
  });

  return Object.keys(balances).map(friend => ({
    friend,
    amount: balances[friend]
  }));
}

import { Expense } from '../types';

export function parseExpense(input: string): Expense | null {
  const parts = input.split(',');
  if (parts.length !== 3) return null;
  const [description, amountStr, date] = parts;
  const amount = parseFloat(amountStr);
  if (isNaN(amount)) return null;
  return { description, amount, date };
}

