export interface ContactItem {
  id: number;
  name: string;
  phone: string;
  email: string;
  tags: string[];
}

let contacts: ContactItem[] = [];

export function addContact(name: string, phone: string, email: string, tags: string[]): void {
  const newContact: ContactItem = {
    id: Date.now(),
    name,
    phone,
    email,
    tags,
  };
  contacts.push(newContact);
}

export function listContacts(): ContactItem[] {
  return contacts;
}

export function searchContacts(query: string): ContactItem[] {
  return contacts.filter(c => c.name.toLowerCase().includes(query.toLowerCase()) || c.tags.some(t => t.toLowerCase().includes(query.toLowerCase())));
}

export function editContact(id: number, name: string, phone: string, email: string, tags: string[]): boolean {
  const index = contacts.findIndex(c => c.id === id);
  if (index === -1) return false;
  contacts[index] = { id, name, phone, email, tags };
  return true;
}

export function deleteContact(id: number): boolean {
  const index = contacts.findIndex(c => c.id === id);
  if (index === -1) return false;
  contacts.splice(index, 1);
  return true;
}

