import express from 'express';
import { Note } from './models';

const notes: Note[] = [];

export function startAPI(port: number): void {
  const app = express();
  app.use(express.json());

  app.get('/notes', (req, res) => {
    res.json(notes);
  });

  app.post('/notes', (req, res) => {
    const note = req.body;
    notes.push(note);
    res.status(201).json(note);
  });

  app.listen(port, () => {
    console.log(`API server listening on port ${port}`);
  });
}

import { getNotes, addNote, deleteNote } from './api';

function renderNotes(list: HTMLUListElement): void {
  list.innerHTML = '';
  getNotes().forEach(note => {
    const li = document.createElement('li');
    const p = document.createElement('p');
    p.textContent = note.content;
    const deleteBtn = document.createElement('button');
    deleteBtn.textContent = 'Delete';
    deleteBtn.onclick = () => {
      deleteNote(note.id);
      renderNotes(list);
    };
    li.append(p, deleteBtn);
    list.appendChild(li);
  });
}

export function startFrontend(): void {
  const input = document.createElement('input');
  input.placeholder = 'Add a note';
  const addBtn = document.createElement('button');
  addBtn.textContent = 'Add Note';
  const list = document.createElement('ul');
  addBtn.onclick = () => {
    const content = input.value.trim();
    if (!content) return;
    addNote({ content });
    input.value = '';
    renderNotes(list);
  };
  renderNotes(list);
  document.body.append(input, addBtn, list);
}

