    const createResponse = await request(app).post('/notes').send({ title: 'Test Note', content: 'This is a test note.' });
    const noteId = createResponse.body.id;
    const response = await request(app).put(`/notes/${noteId}`).send({ title: 'Updated Note', content: 'This is an updated note.' });
    expect(response.status).toBe(200);
    expect(response.body.id).toBe(noteId);
    expect(response.body.title).toBe('Updated Note');
    expect(response.body.content).toBe('This is an updated note.');
  });

  it('should delete a note by ID', async () => {
    const createResponse = await request(app).post('/notes').send({ title: 'Test Note', content: 'This is a test note.' });
    const noteId = createResponse.body.id;
    const deleteResponse = await request(app).delete(`/notes/${noteId}`);
    expect(deleteResponse.status).toBe(204);
    const getResponse = await request(app).get(`/notes/${noteId}`);
    expect(getResponse.status).toBe(404);
