export const CONFIG = {
  logLevels: ['info', 'warning', 'error'],
  maxErrors: 5,
};

import { parseLog } from './logParser';
import { countLevels } from './logCounter';
import { reportTopModules } from './logReporter';

export function analyzeLog(log: string): string {
  const parsedLog = parseLog(log);
  const levelCounts = countLevels(parsedLog);
  return reportTopModules(levelCounts);
}

export function countLevels(logLines: string[]): { [key: string]: number } {
  const levelCounts: { [key: string]: number } = {};
  for (const line of logLines) {
    const level = line.split(' ')[0];
    if (levelCounts[level]) {
      levelCounts[level]++;
    } else {
      levelCounts[level] = 1;
    }
  }
  return levelCounts;
}

export function parseLog(log: string): { level: string, message: string }[] {
  const lines = log.split('\n');
  const parsedLogs: { level: string, message: string }[] = [];

  for (const line of lines) {
    const match = line.match(/^\[(error|warning|info)\] - (.*)$/);
    if (match) {
      parsedLogs.push({ level: match[1], message: match[2] });
    }
  }

  return parsedLogs;
}

import { LogEntry, LogLevel } from './types';

export function parseLog(log: string): LogEntry[] {
  const entries: LogEntry[] = [];
  const lines = log.split('\n');
  for (const line of lines) {
    const match = line.match(/^\[(error|warning|info)\] - (.+)$/);
    if (match) {
      const level = match[1] as LogLevel;
      const message = match[2];
      entries.push({ level, message });
    }
  }
  return entries;
}

export function countLevels(entries: LogEntry[]): { [key in LogLevel]: number } {
  const counts: { [key in LogLevel]: number } = { error: 0, warning: 0, info: 0 };
  for (const entry of entries) {
    counts[entry.level]++;
  }
  return counts;
}

import { LogEntry } from './types';

export function reportTopModules(logEntries: LogEntry[]): string {
  const moduleCounts: { [key: string]: number } = {};

  for (const entry of logEntries) {
    if (entry.level === 'error') {
      moduleCounts[entry.module] = (moduleCounts[entry.module] || 0) + 1;
    }
  }

  const sortedModules = Object.entries(moduleCounts).sort((a, b) => b[1] - a[1]);
  const topModules = sortedModules.slice(0, 3);

  return topModules.map(([module, count]) => `${module}: ${count} errors`).join('\n');
}

export enum LogLevel {
  INFO = 'INFO',
  WARN = 'WARN',
  ERROR = 'ERROR',
}

export interface LogEntry {
