export class Timer {
  private intervalId: NodeJS.Timeout | null = null;
  private remainingSeconds: number = 0;
  private isRunning: boolean = false;
  private history: { type: 'work' | 'break', duration: number }[] = [];

  constructor(private workDuration: number, private breakDuration: number) {}

  start(type: 'work' | 'break') {
    if (this.isRunning) return;
    this.isRunning = true;
    this.remainingSeconds = type === 'work' ? this.workDuration * 60 : this.breakDuration * 60;
    this.intervalId = setInterval(() => {
      if (this.remainingSeconds > 0) {
        this.remainingSeconds -= 1;
      } else {
        this.stop();
      }
    }, 1000);
  }

  stop() {
    if (!this.isRunning) return;
    this.isRunning = false;
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  undo() {
    if (this.history.length === 0) return;
    const last = this.history.pop();
    if (last) {
      this.remainingSeconds = last.duration;
    }
  }
}

