function parseArgs(args: string[]): { cmd: string, id?: number, desc?: string } {
  if (args.length < 1) return { cmd: 'list' };
  const cmd = args[0];
  if (cmd === 'add' && args.length > 1) return { cmd, desc: args.slice(1).join(' ') };
  if (cmd === 'complete' && args.length > 1) {
    const id = parseInt(args[1], 10);
    if (isNaN(id)) throw new Error('Invalid todo ID');
    return { cmd, id };
  }
  return { cmd };
}

function run(cmd: string, id?: number, desc?: string): void {
  switch (cmd) {
    case 'add':
      if (!desc) throw new Error('Missing todo description');
      addTodo(desc);
      console.log('Todo added');
      break;
    case 'list':
      const todos = listTodos();
      if (todos.length === 0) console.log('No todos');
      else todos.forEach(t => console.log(`#${t.id}: ${t.completed ? '✓' : '✗'} ${t.desc}`));
      break;
    case 'complete':
      if (!id) throw new Error('Missing todo ID');
      completeTodo(id);
      console.log('Todo completed');
      break;
    default:
      throw new Error(`Unknown command: ${cmd}`);
  }
}

try {
  const { cmd, id, desc } = parseArgs(process.argv.slice(2));
  run(cmd, id, desc);
} catch (err) {
