export function processCommand(command: string, player: { currentRoom: string, inventory: string[] }): string {
  const cmd = command.trim().toLowerCase();
  if (cmd === 'look') {
    return `You are in the ${player.currentRoom}.`;
  } else if (cmd.startsWith('take ')) {
    const item = cmd.slice(5).trim();
    if (item) {
      player.inventory.push(item);
      return `You picked up the ${item}.`;
    } else {
      return 'What do you want to take?';
    }
  } else if (cmd.startsWith('move ')) {
    const room = cmd.slice(5).trim();
    if (room) {
      player.currentRoom = room;
      return `You moved to the ${room}.`;
    } else {
      return 'Where do you want to move?';
    }
  } else {
    return 'Unknown command.';
  }
}

