export class Game {
  currentRoomId: string;
  inventory: string[];
  rooms: { [key: string]: Room };
  items: { [key: string]: Item };

  constructor() {
    this.currentRoomId = 'start';
    this.inventory = [];
    this.rooms = {
      start: new Room('start', 'You are in a small room. There is a door to the north.', ['key'], { north: 'hall' }),
      hall: new Room('hall', 'You are in a long hallway. There is a door to the east and west.', ['sword'], { east: 'kitchen', west: 'bedroom' }),
      kitchen: new Room('kitchen', 'You are in a cozy kitchen. There is a door to the west.', ['apple'], { west: 'hall' }),
      bedroom: new Room('bedroom', 'You are in a bedroom. There is a door to the east.', ['pillow'], { east: 'hall' })
    };
    this.items = {
      key: new Item('key', 'A small key'),
      sword: new Item('sword', 'A sharp sword'),
      apple: new Item('apple', 'A red apple'),
      pillow: new Item('pillow', 'A soft pillow')
    };
  }

  look() {
    const room = this.rooms[this.currentRoomId];
    return room.description + '\nItems: ' + room.items.join(', ') + '\nExits: ' + Object.keys(room.exits).join(', ');
  }

  take(item: string) {
    const room = this.rooms[this.currentRoomId];
    if (room.items.includes(item)) {
      this.inventory.push(item);
      room.items = room.items.filter(i => i !== item);
      return `You picked up the ${item}.`;
    }
    return `There is no ${item} here.`;
  }

  move(direction: string) {
    const room = this.rooms[this.currentRoomId];
    if (room.exits[direction]) {
      this.currentRoomId = room.exits[direction];
      return `You moved ${direction}.`;
    }
    return `You can't go that way.`;
  }
}

