export class Board {
  private grid: string[];

  constructor() {
    this.grid = Array(9).fill('');
  }

  public getCell(index: number): string {
    return this.grid[index];
  }

  public setCell(index: number, player: string): void {
    this.grid[index] = player;
  }

  public isFull(): boolean {
    return this.grid.every(cell => cell !== '');
  }

  public checkWin(player: string): boolean {
    const winningLines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
      [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
      [0, 4, 8], [2, 4, 6]            // Diagonals
    ];

    for (const line of winningLines) {
      if (line.every(index => this.grid[index] === player)) {
        return true;
      }
    }

    return false;
  }
}

export class Game {
  private board: Board;
  private currentPlayer: string;

  constructor() {
    this.board = new Board();
    this.currentPlayer = 'X';
  }

  public play(index: number): boolean {
    if (this.board.getCell(index) !== '') {
      return false;
    }

    this.board.setCell(index, this.currentPlayer);
    return true;
  }

  public switchPlayer(): void {
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
  }

  public checkWin(): boolean {
    return this.board.checkWin(this.currentPlayer);
  }

  public isFull(): boolean {
    return this.board.isFull();
  }

  public getCurrentPlayer(): string {
    return this.currentPlayer;
  }
}

