export function playGame() {
  let board = Array(9).fill(null);
  let currentPlayer = 'X';

  while (true) {
    renderBoard(board);
    const index = getPlayerInput(board);
    board[index] = currentPlayer;
    const winner = checkWinner(board);
    if (winner) {
      console.log(`Player ${winner} wins!`);
      break;
    }
    if (board.every(cell => cell !== null)) {
      console.log('It\'s a tie!');
      break;
    }
    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  }
}

function checkWinner(board: (string | null)[]) {
  const winningLines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];
  for (const line of winningLines) {
    const [a, b, c] = line;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return board[a];
    }
  }
  return null;
}

export interface GameState {
  board: string[];
  currentPlayer: 'X' | 'O';
  winner: 'X' | 'O' | null;
  isTie: boolean;
}

export class GameLogic {
  private board: string[];
  private currentPlayer: 'X' | 'O';
  private winner: 'X' | 'O' | null;
  private isTie: boolean;

  constructor() {
    this.board = Array(9).fill('');
    this.currentPlayer = 'X';
    this.winner = null;
    this.isTie = false;
  }

  public play(index: number): void {
    if (this.board[index] !== '' || this.winner !== null || this.isTie) {
      return;
    }
    this.board[index] = this.currentPlayer;
    this.checkWin();
    this.checkTie();
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
  }

  public getGameState(): GameState {
    return {
      board: this.board,
      currentPlayer: this.currentPlayer,
      winner: this.winner,
      isTie: this.isTie,
    };
  }

  private checkWin(): void {
    const winningLines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (const line of winningLines) {
      const [a, b, c] = line;
      if (this.board[a] && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
        this.winner = this.board[a];
        return;
      }
    }
  }

  private checkTie(): void {
    if (!this.board.includes('') && this.winner === null) {
      this.isTie = true;
    }
  }
}

