export class Game {
  private board: string[];
  private currentPlayer: string;

  constructor() {
    this.board = Array(9).fill(null);
    this.currentPlayer = 'X';
  }

  public play(index: number): boolean {
    if (this.board[index] || this.checkWinner()) {
      return false;
    }
    this.board[index] = this.currentPlayer;
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    return true;
  }

  public checkWinner(): string | null {
    const winningLines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];
    for (const line of winningLines) {
      const [a, b, c] = line;
      if (this.board[a] && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
        return this.board[a];
      }
    }
    return null;
  }

  public isDraw(): boolean {
    return this.board.every(cell => cell !== null);
  }

  public getBoard(): string[] {
    return this.board;
  }

  public getCurrentPlayer(): string {
    return this.currentPlayer;
  }
}

export class MinMaxComputer {
  private game: Game;

  constructor(game: Game) {
    this.game = game;
  }

  public makeMove(): void {
    const bestMove = this.minimax(0, true);
    if (bestMove !== null) {
      this.game.play(bestMove);
    }
  }

  private minimax(depth: number, isMaximizing: boolean): number | null {
    const winner = this.game.checkWinner();
    if (winner === 'X') {
      return 10 - depth;
    } else if (winner === 'O') {
      return depth - 10;
    } else if (this.game.isDraw()) {
      return 0;
    }

    let bestMove: number | null = null;
    let bestScore: number;

    if (isMaximizing) {
      bestScore = -Infinity;
      for (let i = 0; i < 9; i++) {
        if (this.game.getBoard()[i] === null) {
          this.game.play(i);
          const score = this.minimax(depth + 1, false);
          this.game.play(i);
          if (score !== null && score > bestScore) {
            bestScore = score;
            bestMove = i;
          }
        }
      }
    } else {
      bestScore = Infinity;
      for (let i = 0; i < 9; i++) {
        if (this.game.getBoard()[i] === null) {
          this.game.play(i);
          const score = this.minimax(depth + 1, true);
          this.game.play(i);
          if (score !== null && score < bestScore) {
            bestScore = score;
            bestMove = i;
          }
        }
      }
    }

    return bestMove;
  }
}

export function play(board: string[], player: string): string[] {
  const emptyIndices = board.map((cell, index) => (cell === '' ? index : -1)).filter(index => index !== -1);
  if (emptyIndices.length === 0) return board;

  const bestMove = minimax(board, player);
  if (bestMove !== -1) board[bestMove] = player;
  return board;
}

function minimax(board: string[], player: string, depth = 0): number {
  const winner = checkWinner(board);
  if (winner === 'X') return 10 - depth;
  if (winner === 'O') return depth - 10;
  if (winner === 'draw') return 0;

  const emptyIndices = board.map((cell, index) => (cell === '' ? index : -1)).filter(index => index !== -1);
  if (emptyIndices.length === 0) return 0;

  let bestScore = player === 'X' ? -Infinity : Infinity;
  let bestMove = -1;

  for (const index of emptyIndices) {
    board[index] = player;
    const score = minimax(board, player === 'X' ? 'O' : 'X', depth + 1);
    board[index] = '';
    if (player === 'X' && score > bestScore) {
      bestScore = score;
      bestMove = index;
    } else if (player === 'O' && score < bestScore) {
      bestScore = score;
      bestMove = index;
    }
  }

  return bestMove;
}

