export enum Player {
  X = 'X',
  O = 'O',
  Empty = ' ',
}

export class TicTacToe {
  private board: Player[];
  private currentPlayer: Player;

  constructor() {
    this.board = new Array(9).fill(Player.Empty);
    this.currentPlayer = Player.X;
  }

  public play(index: number): boolean {
    if (index < 0 || index >= 9 || this.board[index] !== Player.Empty) {
      return false;
    }
    this.board[index] = this.currentPlayer;
    this.currentPlayer = this.currentPlayer === Player.X ? Player.O : Player.X;
    return true;
  }

  public getBoard(): Player[] {
    return this.board;
  }

  public getCurrentPlayer(): Player {
    return this.currentPlayer;
  }

  public checkWinner(): Player | null {
    const winningLines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
      [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
      [0, 4, 8], [2, 4, 6],           // Diagonals
    ];

    for (const line of winningLines) {
      const [a, b, c] = line;
      if (this.board[a] !== Player.Empty && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
        return this.board[a];
      }
    }

    return null;
  }

  public isBoardFull(): boolean {
    return this.board.every(cell => cell !== Player.Empty);
  }
}

export function minimax(board: Player[], depth: number, isMaximizing: boolean): number {
  const winner = checkWinner(board);
  if (winner === Player.X) return 1;
  if (winner === Player.O) return -1;
  if (board.every(cell => cell !== Player.Empty)) return 0;

  if (isMaximizing) {
    let maxEval = -Infinity;
    for (let i = 0; i < 9; i++) {
      if (board[i] === Player.Empty) {
        board[i] = Player.X;
        maxEval = Math.max(maxEval, minimax(board, depth + 1, false));
        board[i] = Player.Empty;
      }
    }
    return maxEval;
  } else {
    let minEval = Infinity;
    for (let i = 0; i < 9; i++) {
      if (board[i] === Player.Empty) {
        board[i] = Player.O;
        minEval = Math.min(minEval, minimax(board, depth + 1, true));
        board[i] = Player.Empty;
      }
    }
    return minEval;
  }
}

function checkWinner(board: Player[]): Player | null {
  const winningLines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
    [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
    [0, 4, 8], [2, 4, 6],           // Diagonals
  ];

  for (const line of winningLines) {
    const [a, b, c] = line;
    if (board[a] !== Player.Empty && board[a] === board[b] && board[a] === board[c]) {
      return board[a];
    }
  }

  return null;
}

export function parseCSV(csv: string): number[] {
  const lines = csv.trim().split('\n');
  const prices: number[] = [];
  for (const line of lines) {
    const parts = line.split(',');
    if (parts.length !== 2) continue;
    const price = parseFloat(parts[1]);
    if (!isNaN(price)) prices.push(price);
  }
  return prices;
}

export function calculateMovingAverage(prices: number[], windowSize: number): number[] {
  const averages: number[] = [];
  for (let i = 0; i <= prices.length - windowSize; i++) {
    const sum = prices.slice(i, i + windowSize).reduce((acc, p) => acc + p, 0);
    averages.push(sum / windowSize);
  }
  return averages;
}

