export class PollService {
  private polls: Poll[] = [];

  createPoll(question: string, options: string[]): Poll {
    const poll: Poll = {
      id: this.polls.length + 1,
      question,
      options,
      votes: []
    };
    this.polls.push(poll);
    return poll;
  }

  castVote(pollId: number, option: string): void {
    const poll = this.polls.find(p => p.id === pollId);
    if (poll) {
      poll.votes.push({ option });
    }
  }

  getResults(pollId: number): { option: string, percentage: number }[] {
    const poll = this.polls.find(p => p.id === pollId);
    if (!poll) return [];
    const totalVotes = poll.votes.length;
    const results: { option: string, percentage: number }[] = [];
    poll.options.forEach(option => {
      const count = poll.votes.filter(v => v.option === option).length;
      results.push({ option, percentage: (count / totalVotes) * 100 });
    });
    return results;
  }
}

